const GLOSS_PID = '46552447679363c70f7ef8.58193285';
return [{ json: {
  project_id: GLOSS_PID,
  languages_url: 'https://api.lokalise.com/api2/projects/' + GLOSS_PID + '/languages?limit=500',
  read_url: 'https://api.lokalise.com/api2/projects/' + GLOSS_PID + '/glossary-terms?limit=500&pagination=cursor'
} }];

const plan = $('Plan').first().json;
const lr = $('Fetch languages').first().json || {};
const lb = (lr.body !== undefined) ? lr.body : lr;
const projectLangs = lb.languages || [];

const isoById = {};
const nameById = {};
const langOrder = [];
for (const L of projectLangs) {
  const id = Number(L.lang_id);
  isoById[String(id)] = L.lang_iso;
  nameById[String(id)] = L.lang_name;
  langOrder.push(id);
}

const live = {};
const pages = [];
for (const p of $input.all()) {
  const r = p.json || {};
  const b = (r.body !== undefined) ? r.body : r;
  const arr = b.data || b.glossary_terms || [];
  pages.push({ status: r.statusCode || null, terms: arr.length });
  for (const t of arr) { live[String(t.id)] = t; }
}

const termIds = Object.keys(live);
const filled = {};
const empty = {};
for (const id of langOrder) { filled[String(id)] = 0; empty[String(id)] = 0; }
const strayLangIds = {};

const terms = [];
for (const tid of termIds) {
  const t = live[tid];
  const byId = {};
  for (const x of (t.translations || [])) {
    const lid = String(Number(x.langId));
    byId[lid] = String(x.translation || '').trim();
    if (isoById[lid] === undefined) { strayLangIds[lid] = (strayLangIds[lid] || 0) + 1; }
  }
  const missing = [];
  const has = [];
  for (const id of langOrder) {
    const k = String(id);
    const v = byId[k];
    if (v === undefined || v === '') { empty[k] = empty[k] + 1; missing.push(isoById[k]); }
    else { filled[k] = filled[k] + 1; has.push(isoById[k]); }
  }
  terms.push({
    id: Number(t.id),
    term: t.term,
    description: t.description || '',
    translatable: t.translatable,
    forbidden: t.forbidden,
    caseSensitive: t.caseSensitive,
    tags: t.tags || [],
    filled_count: has.length,
    missing_count: missing.length,
    filled_isos: has,
    missing_isos: missing,
    values: byId
  });
}

terms.sort(function (a, b) { return String(a.term).toLowerCase().localeCompare(String(b.term).toLowerCase()); });

const perLocale = [];
for (const id of langOrder) {
  const k = String(id);
  perLocale.push({ langId: id, iso: isoById[k], name: nameById[k], filled: filled[k], missing: empty[k] });
}
perLocale.sort(function (a, b) { return b.missing - a.missing; });

return [{ json: {
  project_id: plan.project_id,
  pages: pages,
  page_count: pages.length,
  term_count: termIds.length,
  project_language_count: langOrder.length,
  stray_lang_ids: strayLangIds,
  per_locale: perLocale,
  terms: terms
} }];
